alter table public.groups add column if not exists activity_status text not null default 'not_started' check (activity_status in ('not_started','in_progress','review','completed'));
alter table public.groups add column if not exists photo_url text;
alter table public.recipes add column if not exists is_locked boolean not null default false;
create table if not exists public.classroom_settings (id integer primary key default 1 check (id=1), announcement text, announcement_updated_at timestamptz not null default now(), updated_by uuid references auth.users(id));
insert into public.classroom_settings(id) values (1) on conflict (id) do nothing;
create table if not exists public.activity_history (id bigint generated by default as identity primary key, group_id uuid references public.groups(id) on delete cascade, actor_id uuid references auth.users(id) on delete set null, action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists activity_history_group_idx on public.activity_history(group_id, created_at desc);
alter table public.classroom_settings enable row level security;
alter table public.activity_history enable row level security;
drop policy if exists classroom_settings_read on public.classroom_settings;
create policy classroom_settings_read on public.classroom_settings for select to anon, authenticated using (true);
drop policy if exists classroom_settings_teacher_update on public.classroom_settings;
create policy classroom_settings_teacher_update on public.classroom_settings for update to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher')) with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher'));
drop policy if exists activity_history_teacher_read on public.activity_history;
create policy activity_history_teacher_read on public.activity_history for select to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher'));
insert into storage.buckets(id,name,public) values ('activity-photos','activity-photos',true) on conflict (id) do update set public=true;
drop policy if exists activity_photos_teacher_insert on storage.objects;
create policy activity_photos_teacher_insert on storage.objects for insert to authenticated with check (bucket_id='activity-photos' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher'));
drop policy if exists activity_photos_teacher_update on storage.objects;
create policy activity_photos_teacher_update on storage.objects for update to authenticated using (bucket_id='activity-photos' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher')) with check (bucket_id='activity-photos' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher'));
drop policy if exists activity_photos_teacher_delete on storage.objects;
create policy activity_photos_teacher_delete on storage.objects for delete to authenticated using (bucket_id='activity-photos' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher'));

drop function if exists public.set_group_status(uuid,text);
create function public.set_group_status(target_group_id uuid,new_status text) returns public.groups language plpgsql security definer set search_path=public,auth as $$declare r public.groups; role_name text;begin select role into role_name from public.profiles where id=auth.uid(); if role_name is distinct from 'teacher' then raise exception 'Apenas professores podem alterar o status.'; end if; if new_status not in ('not_started','in_progress','review','completed') then raise exception 'Status inválido.'; end if; update public.groups set activity_status=new_status where id=target_group_id returning * into r; if not found then raise exception 'Grupo não encontrado.'; end if; if new_status='completed' then update public.recipes set is_locked=true where group_id=target_group_id; elsif new_status in ('in_progress','review') then update public.recipes set is_locked=false where group_id=target_group_id; end if; insert into public.activity_history(group_id,actor_id,action,details) values(target_group_id,auth.uid(),'status_changed',jsonb_build_object('status',new_status)); return r;end;$$;
grant execute on function public.set_group_status(uuid,text) to authenticated;

drop function if exists public.set_announcement(text);
create function public.set_announcement(new_announcement text) returns public.classroom_settings language plpgsql security definer set search_path=public,auth as $$declare r public.classroom_settings;begin if not exists(select 1 from public.profiles where id=auth.uid() and role='teacher') then raise exception 'Apenas professores podem publicar avisos.'; end if; update public.classroom_settings set announcement=nullif(trim(new_announcement),''),announcement_updated_at=now(),updated_by=auth.uid() where id=1 returning * into r; insert into public.activity_history(actor_id,action,details) values(auth.uid(),'announcement_changed',jsonb_build_object('has_announcement',r.announcement is not null)); return r;end;$$;
grant execute on function public.set_announcement(text) to authenticated;

drop function if exists public.set_group_photo(uuid,text);
create function public.set_group_photo(target_group_id uuid,new_photo_url text) returns public.groups language plpgsql security definer set search_path=public,auth as $$declare r public.groups;begin if not exists(select 1 from public.profiles where id=auth.uid() and role='teacher') then raise exception 'Apenas professores podem atualizar a foto.'; end if; update public.groups set photo_url=nullif(trim(new_photo_url),'') where id=target_group_id returning * into r; if not found then raise exception 'Grupo não encontrado.'; end if; insert into public.activity_history(group_id,actor_id,action,details) values(target_group_id,auth.uid(),'photo_changed',jsonb_build_object('has_photo',r.photo_url is not null)); return r;end;$$;
grant execute on function public.set_group_photo(uuid,text) to authenticated;

create or replace function public.save_recipe_classroom(target_recipe_id uuid,new_title text,new_ingredients text,new_instructions text,new_notes text) returns public.recipes language plpgsql security definer set search_path=public,auth as $$declare r public.recipes; role_name text; uid uuid;begin uid:=auth.uid(); select role into role_name from public.profiles where id=uid; select * into r from public.recipes where id=target_recipe_id; if r.id is null then raise exception 'Receita não encontrada.'; end if; if r.is_locked then raise exception 'Esta receita está finalizada e bloqueada.'; end if; if role_name<>'teacher' and not exists(select 1 from public.profiles where id=uid and group_id=r.group_id) then raise exception 'Você não pertence a este grupo.'; end if; update public.recipes set title=trim(new_title),ingredients=trim(new_ingredients),instructions=trim(new_instructions),notes=nullif(trim(new_notes),''),updated_by=uid,updated_at=now() where id=target_recipe_id returning * into r; insert into public.activity_history(group_id,actor_id,action,details) values(r.group_id,uid,'recipe_saved',jsonb_build_object('recipe_id',r.id,'title',r.title)); return r;end;$$;
grant execute on function public.save_recipe_classroom(uuid,text,text,text,text) to authenticated;

create or replace function public.set_recipe_lock(target_recipe_id uuid,new_locked boolean) returns public.recipes language plpgsql security definer set search_path=public,auth as $$declare r public.recipes;begin if not exists(select 1 from public.profiles where id=auth.uid() and role='teacher') then raise exception 'Apenas professores podem bloquear receitas.'; end if; update public.recipes set is_locked=new_locked,updated_at=now() where id=target_recipe_id returning * into r; if r.id is null then raise exception 'Receita não encontrada.'; end if; insert into public.activity_history(group_id,actor_id,action,details) values(r.group_id,auth.uid(),case when new_locked then 'recipe_locked' else 'recipe_unlocked' end,jsonb_build_object('recipe_id',r.id)); return r;end;$$;
grant execute on function public.set_recipe_lock(uuid,boolean) to authenticated;

drop function if exists public.guard_recipe_classroom();
create function public.guard_recipe_classroom() returns trigger language plpgsql security definer set search_path=public,auth as $$declare role_name text; status_name text;begin select role into role_name from public.profiles where id=auth.uid(); select activity_status into status_name from public.groups where id=coalesce(new.group_id,old.group_id); if tg_op='INSERT' and status_name='completed' and role_name<>'teacher' then raise exception 'A atividade deste grupo já foi finalizada.'; end if; if tg_op='UPDATE' and old.is_locked and role_name<>'teacher' then raise exception 'Esta receita está finalizada e bloqueada.'; end if; if tg_op='DELETE' and role_name<>'teacher' then raise exception 'Apenas o professor pode excluir receitas.'; end if; return coalesce(new,old);end;$$;
drop trigger if exists recipes_classroom_guard on public.recipes;
create trigger recipes_classroom_guard before insert or update or delete on public.recipes for each row execute function public.guard_recipe_classroom();

drop function if exists public.log_recipe_activity();
create function public.log_recipe_activity() returns trigger language plpgsql security definer set search_path=public,auth as $$begin if tg_op='INSERT' then insert into public.activity_history(group_id,actor_id,action,details) values(new.group_id,auth.uid(),'recipe_created',jsonb_build_object('recipe_id',new.id,'title',new.title)); elsif tg_op='DELETE' then insert into public.activity_history(group_id,actor_id,action,details) values(old.group_id,auth.uid(),'recipe_deleted',jsonb_build_object('recipe_id',old.id,'title',old.title)); elsif tg_op='UPDATE' and (old.title is distinct from new.title or old.ingredients is distinct from new.ingredients or old.instructions is distinct from new.instructions or old.notes is distinct from new.notes) then insert into public.activity_history(group_id,actor_id,action,details) values(new.group_id,auth.uid(),'recipe_updated',jsonb_build_object('recipe_id',new.id,'title',new.title)); end if; return coalesce(new,old);end;$$;
drop trigger if exists recipes_activity_log on public.recipes;
create trigger recipes_activity_log after insert or update or delete on public.recipes for each row execute function public.log_recipe_activity();

create or replace function public.get_group_overview() returns table(group_id uuid,name text,slug text,description text,activity_status text,photo_url text,member_count bigint,recipe_count bigint) language sql security definer set search_path=public,auth as $$select g.id,g.name,g.slug,g.description,g.activity_status,g.photo_url,(select count(*) from public.profiles p where p.group_id=g.id and p.is_anonymous=false),(select count(*) from public.recipes r where r.group_id=g.id) from public.groups g order by g.slug;$$;
grant execute on function public.get_group_overview() to anon,authenticated;

create or replace function public.get_group_history(target_group_id uuid) returns setof public.activity_history language sql security definer set search_path=public,auth as $$select h.* from public.activity_history h where h.group_id=target_group_id and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher') order by h.created_at desc limit 100;$$;
grant execute on function public.get_group_history(uuid) to authenticated;
